-- 90_VERIFY.sql — 적용 후 단언 (조회 전용) [E20261002-DMF0082-81MKTAMT]
SET PAGESIZE 200 LINESIZE 250
COLUMN JUDGE FORMAT A40
PROMPT [V1] VALID · 오류 0
SELECT O.OBJECT_TYPE, O.STATUS, TO_CHAR(O.LAST_DDL_TIME,'YYYY-MM-DD HH24:MI:SS') LAST_DDL,
       (SELECT COUNT(*) FROM USER_ERRORS E WHERE E.NAME=O.OBJECT_NAME AND E.TYPE=O.OBJECT_TYPE) ERR_CNT,
       CASE WHEN O.STATUS='VALID' AND (SELECT COUNT(*) FROM USER_ERRORS E WHERE E.NAME=O.OBJECT_NAME AND E.TYPE=O.OBJECT_TYPE)=0
            THEN 'PASS' ELSE '❌ FAIL' END JUDGE
  FROM USER_OBJECTS O WHERE O.OBJECT_NAME='PKG_DMF0082' ORDER BY O.OBJECT_TYPE;
PROMPT [V2] 금액 arm 4 (MAIN Current·MF·SF + CURRENT) · 원천 읽기 4 (DM_PLN_SALES_PLAN 2 + _C 2) (11 적용 시 지문 16662/864802)
SELECT LN || '/' || CH BODY_FP, (SELECT COUNT(*) FROM USER_SOURCE WHERE NAME='PKG_DMF0082' AND TYPE='PACKAGE BODY' AND TEXT LIKE '%END IF;  --[E20261002-DMF0082-81MKTAMT]%') MARK_BLOCKS, (SELECT COUNT(*) FROM USER_SOURCE WHERE NAME='PKG_DMF0082' AND TYPE='PACKAGE BODY' AND (TEXT LIKE '%FROM   SCM_MGR.DM_PLN_SALES_PLAN S%' OR TEXT LIKE '%FROM   SCM_MGR.DM_PLN_SALES_PLAN_C S%')) SALES_PLAN_READS,
       CASE WHEN (SELECT COUNT(*) FROM USER_SOURCE WHERE NAME='PKG_DMF0082' AND TYPE='PACKAGE BODY' AND TEXT LIKE '%END IF;  --[E20261002-DMF0082-81MKTAMT]%') = 4 AND (SELECT COUNT(*) FROM USER_SOURCE WHERE NAME='PKG_DMF0082' AND TYPE='PACKAGE BODY' AND (TEXT LIKE '%FROM   SCM_MGR.DM_PLN_SALES_PLAN S%' OR TEXT LIKE '%FROM   SCM_MGR.DM_PLN_SALES_PLAN_C S%')) = 4 THEN 'PASS' ELSE '❌ FAIL' END JUDGE
  FROM (SELECT COUNT(*) LN, SUM(LENGTH(RTRIM(TEXT, CHR(10)||CHR(13)))) CH FROM USER_SOURCE WHERE NAME='PKG_DMF0082' AND TYPE='PACKAGE BODY' AND LINE > 1);
PROMPT [V3] 앱 계정 실행 권한 유지
SELECT GRANTEE, PRIVILEGE FROM USER_TAB_PRIVS WHERE TABLE_NAME='PKG_DMF0082' ORDER BY GRANTEE;
PROMPT [V4] 의존 객체 INVALID 0
SELECT (SELECT COUNT(*) FROM USER_DEPENDENCIES D JOIN USER_OBJECTS O ON O.OBJECT_NAME=D.NAME AND O.OBJECT_TYPE=D.TYPE
         WHERE D.REFERENCED_NAME='PKG_DMF0082' AND D.REFERENCED_TYPE='PACKAGE' AND O.STATUS<>'VALID') INVALID_DEPENDENTS,
       CASE WHEN (SELECT COUNT(*) FROM USER_DEPENDENCIES D JOIN USER_OBJECTS O ON O.OBJECT_NAME=D.NAME AND O.OBJECT_TYPE=D.TYPE
                   WHERE D.REFERENCED_NAME='PKG_DMF0082' AND D.REFERENCED_TYPE='PACKAGE' AND O.STATUS<>'VALID') = 0
            THEN 'PASS' ELSE '❌ FAIL — 13 실행' END JUDGE
  FROM DUAL;
